lipExpression=function(o,t){if(!o.lipSync)return o.expression;const at=sceneOffset()+t;let peak=0;for(const c of tracks().filter(c=>c.role==='narration'&&at>=c.start&&at<audioEnd(c))){const buffer=audioBuffers.get(c.id);if(!buffer)continue;const data=buffer.getChannelData(0),start=Math.floor(((at-c.start)*(c.rate||1)+c.offset)*buffer.sampleRate);let sum=0,n=0;for(let i=start;i<Math.min(data.length,start+1024);i+=8){sum+=data[i]*data[i];n++}if(n)peak=Math.max(peak,Math.sqrt(sum/n)*c.volume)}return peak>.025?'talk':o.expression==='talk'?'happy':o.expression};
const baseRender=render;render=function(){baseRender();renderTimeline()};const baseDraw=draw;draw=function(){baseDraw();updatePlayhead()};const baseControls=renderControls;renderControls=function(){baseControls();if($('clipSettings'))renderClipSettings()};
// Persist media with the project in IndexedDB instead of filling localStorage with data URLs.
let dbPromise=null,saveTimer=null,loadGeneration=0;
function database(){return dbPromise??=new Promise((resolve,reject)=>{const r=indexedDB.open('elleson-studio-desktop',2);r.onupgradeneeded=()=>{for(const name of ['workspace','projects'])if(!r.result.objectStoreNames.contains(name))r.result.createObjectStore(name)};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function storeWorkspace(snapshot){const db=await database();return new Promise((resolve,reject)=>{const tx=db.transaction('workspace','readwrite');tx.objectStore('workspace').put(snapshot,'current');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
save=function(){project.title=$('title').value;const snap=JSON.stringify(project);if(historyStack.at(-1)!==snap){historyStack.push(snap);if(historyStack.length>30)historyStack.shift();futureStack=[]}clearTimeout(saveTimer);$('saveStatus').textContent='Saving…';saveTimer=setTimeout(()=>storeWorkspace(JSON.parse(snap)).then(()=>$('saveStatus').textContent='Saved on this device').catch(()=>{$('saveStatus').textContent='Save failed · download backup';toast('Could not autosave. Download a project backup.')}),300)};
