const originalValid=valid;valid=function(p){return originalValid(p)&&(!p.audioClips||(Array.isArray(p.audioClips)&&p.audioClips.length<100&&p.audioClips.every(c=>c&&typeof c.id==='string'&&typeof c.name==='string'&&['music','narration','effect'].includes(c.role)&&Number.isFinite(c.start)&&c.start>=0&&Number.isFinite(c.duration)&&c.duration>0&&Number.isFinite(c.offset)&&c.offset>=0&&Number.isFinite(c.sourceDuration)&&c.offset+c.duration*(c.rate||1)<=c.sourceDuration+.01&&(c.rate===undefined||Number.isFinite(c.rate)&&c.rate>=.25&&c.rate<=4)&&Number.isFinite(c.volume)&&c.volume>=0&&c.volume<=2&&typeof c.src==='string'&&/^data:(audio|video)\/[a-z0-9.+-]+;base64,/i.test(c.src))))&&p.scenes.every(s=>s.objects.every(o=>(o.in===undefined||Number.isFinite(o.in)&&o.in>=0&&o.in<s.duration)&&(o.out===undefined||Number.isFinite(o.out)&&o.out>=(o.in??0)+.05&&o.out<=s.duration)))};
database().then(db=>new Promise((resolve,reject)=>{const r=db.transaction('workspace').objectStore('workspace').get('current');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})).then(p=>{if(p&&valid(p)){loadProject(p);toast('Workspace restored, including audio.')}else hydrateAudio()}).catch(()=>toast('Autosave unavailable. Download project backups.'));
document.addEventListener('keydown',e=>{if(e.target.matches('input,textarea,select')||document.querySelector('dialog[open]'))return;if(e.code==='Space'){e.preventDefault();if(!recording)play()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();(e.shiftKey?$('redo'):$('undo')).click()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();$('download').click()}});
async function projectRecords(mode,operation){const db=await database();return new Promise((resolve,reject)=>{const tx=db.transaction('projects',mode),request=operation(tx.objectStore('projects'));let result;request.onsuccess=()=>result=request.result;tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error)})}
renderProjects=async function(){try{const entries=await projectRecords('readonly',s=>s.getAll());$('projectList').replaceChildren();if(!entries.length)$('projectList').textContent='No saved projects yet. Save your current project to start.';for(const entry of entries){const row=document.createElement('div');row.className='project-entry';const open=document.createElement('button');open.textContent=entry.project.title+' · '+entry.project.scenes.length+' scenes';open.onclick=()=>{loadProject(structuredClone(entry.project));$('projectDialog').close()};const del=document.createElement('button');del.textContent='Delete';del.onclick=async()=>{if(confirm('Delete this saved project?')){await projectRecords('readwrite',s=>s.delete(entry.id));renderProjects()}};row.append(open,del);$('projectList').append(row)}}catch{toast('Could not load saved projects.')}};
$('saveProject').onclick=async()=>{try{save();project.projectId??=uid();await projectRecords('readwrite',s=>s.put({id:project.projectId,project:structuredClone(project)},project.projectId));renderProjects();toast('Project saved with images and audio.')}catch{toast('Could not save project. Download a project backup.')}};
document.addEventListener('visibilitychange',()=>{if(document.hidden&&!recording)storeWorkspace(project).catch(()=>{})});
const imageImport=$('imageFile').onchange;$('imageFile').accept='image/png,image/jpeg,image/webp,image/gif';$('imageFile').onchange=e=>{const f=e.target.files[0];if(f&&!['image/png','image/jpeg','image/webp','image/gif'].includes(f.type)){e.target.value='';return toast('Choose PNG, JPEG, WebP or GIF.')}imageImport(e)};
render();
// Local preview refreshes after source changes, preserving autosaved work.
if(location.protocol==='http:'||location.protocol==='https:')setInterval(async()=>{if(playing||recording||window.editorTaskBusy||window.canvasDragBusy||timelineDrag||document.querySelector('dialog[open]'))return;try{const r=await fetch('revision.json',{cache:'no-store'}),v=await r.text();if(liveRevision&&v!==liveRevision){await storeWorkspace(project);location.reload()}liveRevision=v}catch{}},1800);
